```java
// Statement — static SQL only (no input)
try (Statement st = con.createStatement();
     ResultSet rs = st.executeQuery("SELECT COUNT(*) FROM users")) { /* ... */ }

// PreparedStatement — parameterized, safe (the default)
try (PreparedStatement ps = con.prepareStatement("SELECT * FROM users WHERE id = ?")) {
    ps.setInt(1, 42);
    try (ResultSet rs = ps.executeQuery()) { /* ... */ }
}

// CallableStatement — stored procedure
try (CallableStatement cs = con.prepareCall("{call get_user(?)}")) {
    cs.setInt(1, 42);
    cs.execute();
}
```

