        con.prepareStatement("SELECT * FROM orders WHERE customer_id = ?")) {
    for (int id : customerIds) {     // many executions
        ps.setInt(1, id);            // just bind...
        try (ResultSet rs = ps.executeQuery()) {  // ...and run the cached plan
            while (rs.next()) { /* ... */ }
        }
    }
}
// the SQL is parsed and planned once, then reused for every id
